INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95996, 'spa', 'Relámpago divino', 'Relámpago o rayo como fenómeno meteorológico bajo el control divino. Job 28:26 y 38:25 hablan de Dios abriendo «un camino para el rayo», resaltando la soberanía divina sobre las tormentas. Zacarías 10:1 lo empareja con los aguaceros en construcción paralela, subrayando su origen celestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95997, 'spa', 'El cerdo', 'El cerdo doméstico o puerco, ritualmente impuro según la ley mosaica. Levítico 11:7 y Deuteronomio 14:8 lo identifican como alimento prohibido porque tiene pezuña hendida pero no rumia. Los oráculos de Isaías contra la apostasía invocan repetidamente al cerdo como símbolo de contaminación ritual: comer carne de cerdo (65:4), ofrecer sangre de cerdo (66:3). Proverbios 11:22 compara a la mujer bella sin discreción con un anillo de oro en el hocico de un cerdo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95999, 'spa', 'El jabalí', 'El jabalí, específicamente el animal destructivo que arrasa las tierras cultivadas. El Salmo 80:14 emplea la frase ''el jabalí del bosque'' como vívida metáfora de los enemigos extranjeros que devastan a Israel, representado como la vid que Dios trasplantó de Egipto. Esta acepción distingue claramente al animal salvaje del cerdo doméstico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96001, 'spa', 'Hifil: reparar edificios', 'Hifil ''reparar edificios'' (36x) concentrado en el relato de la reconstrucción de la muralla por Nehemías, donde dominan las formas participiales: ''los reparadores de'' (Neh 3:4ss). El árabe usa مُرَمِّمِي (participio activo de رَمَّمَ, ''reparar'' —raíz completamente distinta), el español ''reparar''. La conexión con ''fortalecer'' es metafórica: hacer que los muros vuelvan a ser firmes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96002, 'spa', 'Qal: ser fuerte, valiente', 'Qal estativo-intransitivo (62x) que expresa fuerza o valor inherentes, especialmente en las exhortaciones de Moisés: ''¡Esfuérzate y sé valiente!'' (Dt 31:6-7). El árabe emplea تَشَدَّدَ/تَقَوَّى (reflexivos de ''fortalecerse''), el coreano 강하다/용감하다. El sentido no es la superioridad competitiva sino la fortaleza interior: resiliencia emocional, moral o física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96003, 'spa', 'Hifil: asir, agarrar', 'Hifil de aprehensión (46x) que marca el acto deliberado de tomar por la fuerza. Los ángeles ''asieron a Lot de la mano'' (Gn 19:16), el hombre ''la agarró'' (Dt 22:25). El árabe cambia a أَمْسَكَ (raíz m-s-k, ''asir''), el coreano 붙잡다, el español ''asir/agarrar''. Este Hifil causativo transforma la firmeza interior en agarre externo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96004, 'spa', 'Hitpael: fortalecerse', 'Hitpael reflexivo (28x) que marca la fortificación autoiniciada. David ''se fortaleció en YHWH'' (1 S 30:6), ''los israelitas se fortalecieron para la batalla'' (Jue 20:22). El árabe emplea تَشَدَّدَ (Forma V reflexiva, ''templarse'') y تَقَوَّى (''robustecerse''). El Hitpael subraya la agencia propia en la adquisición de fuerza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96006, 'spa', 'Piel: endurecer (corazón)', 'Piel ''endurecer (corazón, rostro)'' (11x) que aparece especialmente en las narrativas del Faraón en Éxodo. ''Yo endureceré su corazón'' (Éx 4:21, 9:12, 10:20, 10:27, 11:10, 14:4, 14:8, 14:17). El árabe emplea قَسَّى (''hacer duro/insensible'', raíz q-s-w), categóricamente distinto de قَوَّى (''fortalecer''). La metáfora hebrea conecta la firmeza (fuerza) con la obstinación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96007, 'spa', 'Piel: fortalecer, animar', 'Piel causativo-factitivo (36x) que significa hacer fuerte a otra persona. ''Fortaleced sus manos para la obra'' (Esd 6:22), Dios dice ''yo te fortaleceré'' (Is 41:10). El árabe usa قَوَّى (Forma II causativa de q-w-y) y شَجَّعَ (''animar''), el español ''fortalecer''. El Piel añade causación transitiva al estado expresado por el Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96008, 'spa', 'Qal: agravarse, intensificarse', 'Qal ''ser severo, intensificarse'' (7x) que describe condiciones, no personas. ''El hambre era severa'' (Gn 41:56), ''el corazón de Faraón se endureció'' (Éx 7:13). El árabe usa اشْتَدَّ (Forma VIII de sh-d-d, ''volverse intenso''). Este Qal estativo describe circunstancias que empeoran —hambruna, plaga, batalla— hasta alcanzar su punto crítico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96010, 'spa', 'Piel: reparar, restaurar', 'Piel ''reparar, restaurar edificios'' (19x) que se solapa con el sentido 3 (Hifil reparar) pero en conjugación Piel. Los reyes ''repararon el templo'' (2 R 12:5-8), Josías ''reparó la casa de YHWH'' (2 Cr 34:8). El árabe usa consistentemente رَمَّمَ (''renovar'' —raíz distinta de قَوَّى y de قَسَّى). El Piel puede enfatizar un proceso más minucioso de restauración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96016, 'spa', 'Hifil: aferrarse, mantener', 'Hifil ''aferrarse, mantenerse firme'' (25x) que describe una sujeción sostenida, a menudo metafórica. ''Si te niegas a dejarlos ir y los retienes todavía'' (Éx 9:2), ''se aferró a su engaño'' (Jer 8:5). El árabe cambia a تَمَسَّكَ (Forma V de m-s-k, ''adherirse''). Este Hifil se distingue del sentido 2 por su carácter continuo frente al asimiento momentáneo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96022, 'spa', 'Qal: prevalecer, vencer', 'Qal ''prevalecer, vencer'' (8x) que marca superioridad en una contienda. ''David prevaleció sobre el filisteo'' (1 S 17:50), ''Amnón forzó a Tamar'' (2 S 13:14). El árabe cambia a غَلَبَ/تَغَلَّبَ (''derrotar'' —raíz completamente distinta gh-l-b). Este sentido Qal implica competición y victoria, no mera fuerza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96052, 'spa', 'Piel: sujetar, asegurar', 'Piel ''sujetar, asegurar objetos'' (4x) aplicado a objetos físicos. ''Sujetan el ídolo para que no se mueva'' (Is 41:7; Jer 10:4), ''para que la estaca no se mueva'' (Is 33:23). El árabe emplea ثَبَّتَ (''fijar en su lugar'', raíz th-b-t), distinto tanto de رَمَّمَ como de قَوَّى. El Piel hace que los objetos queden firmes e inamovibles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96063, 'spa', 'apremiar, urgir', 'Los egipcios ''apremiaron al pueblo'' para que saliera deprisa (Éx 12:33, 1x). La única ocurrencia en el relato del Éxodo sugiere ejercer presión o compulsión. La conexión con ''fortalecer'' puede radicar en la presión intensificadora, aunque algunos lexicones cuestionan la asignación de raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96064, 'spa', 'recuperarse de enfermedad', 'Ezequías ''se había recuperado de su enfermedad'' (Is 39:1, 1x). El Qal perfecto sugiere recuperación completada hasta un estado de firmeza y salud. La única ocurrencia describe el restablecimiento de fuerzas tras la dolencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96085, 'spa', 'Hifil: prevalecer, triunfar', 'Hifil ''prevalecer, ser victorioso'' (2x) que añade fuerza resultativa más allá del Qal (sentido 9). ''La trampa prevalece contra él'' (Job 18:9), ''los que conocen a su Dios se fortalecerán y prevalecerán'' (Dn 11:32). El Hifil enfatiza el logro del dominio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96110, 'spa', 'fortalecer (irónico)', 'Tiglat-pileser ''lo fortaleció'' (2 Cr 28:20, 1x, irónicamente lo oprimió en vez de ayudarlo). El contexto muestra un fortalecimiento pretendido que resultó contraproducente. Referencia histórica única con desenlace irónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96122, 'spa', 'insistir, importunar', 'La viuda ''insistió'' a Eliseo para que se quedara (2 R 4:8, 1x). Similar al sentido 13 (Éx 12:33), la mujer presiona e insta al profeta a aceptar hospitalidad. El sentido se conecta con aplicar presión firme o una invitación persistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96141, 'spa', 'sostener al vulnerable', '''Sostendrás al extranjero y al peregrino'' (Lv 25:35, 1x). Mandato de apoyar y sustentar al desvalido. El Hifil causativo significa hacer que el débil se vuelva firme y estable, solapándose con el sentido 4 (Piel fortalecer) pero en conjugación Hifil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96149, 'spa', 'quedarse atascado', 'La cabeza de Absalón ''se atoró en la encina'' (2 S 18:9, 1x). Ocurrencia única que describe un enredo involuntario. La conexión con ''firme'' radica en quedar sujeto e inmóvil, incapaz de moverse: un asimiento involuntario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96178, 'spa', 'fuerte, poderoso, potente', 'fuerte, poderoso, potente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96182, 'spa', 'severo, feroz, intenso', 'severo, feroz, intenso');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96185, 'spa', 'duro, firme, inflexible', 'duro, firme, inflexible');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96190, 'spa', 'con fuerza, poderosamente', 'con fuerza, poderosamente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96194, 'spa', 'Fuerza o poder', 'Fuerza o poder, especialmente como atributo del poder liberador de Dios. La fórmula del Éxodo ''con fuerza de mano'' (Éx 13:3, 14, 16) conmemora la intervención divina. El español ''fuerza de'' capta uniformemente este sentido de poder abrumador. En Am 6:13 y Hag 2:22, la misma palabra se desplaza hacia la fuerza nacional o militar, con Israel jactándose de su propio poder o Dios derribando los carros de guerra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96195, 'spa', 'Fuerza imperiosa', 'Fuerza o vigor, especialmente como compulsión divina o poderío real en su cúspide. En Isaías 8:11 denota la presión irresistible de la mano de Dios sobre el profeta, impulsándolo a hablar (cf. Ezequiel 3:14). En 2 Crónicas 12:1 y 26:16, marca el instante en que el poder de un rey se consolida —Roboam y Uzías se fortalecieron, y esa misma fortaleza se convirtió en ocasión de caída.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96196, 'spa', 'Fuerza, violencia', 'Fuerza física o coercitiva ejercida sobre otros, generalmente opresiva. La frase be-chozqah aparece en contextos de dominación (Jue 4:3; Ez 34:4), incautación forzosa (1 Sam 2:16) y reprensión severa (Jue 8:1). En Jon 3:8, esa misma fuerza se redirige hacia la oración urgente, mostrando que la intensidad puede servir tanto a la opresión como al arrepentimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96199, 'spa', 'Reforzar, reparar', 'Infinitivo constructo verbal (le-chozqah) de la raíz חָזַק, que significa ''reforzar'' o ''reparar'', funcionando como cláusula de propósito en 2 Re 12:12 respecto a la restauración del Templo. El español ''para reforzar'' capta con precisión la intención constructiva, en marcado contraste con la fuerza coercitiva del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96201, 'spa', 'Ezequías (nombre propio)', 'Nombre propio masculino, compuesto teofórico que significa ''YHWH ha fortalecido''. Su referente principal es el rey reformador de Judá que purificó el culto, resistió la invasión de Senaquerib (2 R 18-19; Is 36-37) y recibió una milagrosa extensión de vida (2 R 20:1-11). Referentes secundarios incluyen un antepasado en 1 Cr 3:23 y una figura postexílica en Sofonías 1:1. Los registros asirios lo nombran Hazakiiahu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96208, 'spa', 'Garfio, anillo de sujeción', 'Un garfio o anillo metálico usado para sujetar cautivos o controlar animales grandes, generalmente insertado en la nariz o la mandíbula. Es el instrumento de la dominación imperial: YHWH amenaza con poner «mi garfio en tu nariz» (2 R 19:28 = Is 37:29), en eco de la práctica asiria de conducir prisioneros con argollas nasales. Ezequiel extiende la imagen a leones jóvenes atrapados con garfios (Ez 19:4, 9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96213, 'spa', 'Broche ornamental', 'Un broche, prendedor o alfiler decorativo, una pieza de joyería personal. Aparece entre los objetos de oro ofrendados para la construcción del Tabernáculo en Éx 35:22, junto con pulseras, pendientes y anillos de sello. El vocabulario cambia notablemente del ámbito del cautiverio al ornamental: tanto el inglés como el francés lo traducen «brooch», y el español emplea «broches».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96215, 'spa', 'Qal: pecar, transgredir', 'Formas finitas e infinitivos del Qal (165 pasajes) que expresan la comisión activa de pecado o falta moral. Todas las formas de persona, número, género y tiempo comparten este significado nuclear. La evidencia interlingüística muestra vocabulario dedicado al pecado: pecado (español), péché (francés), gesündigt (alemán), confirmando a חָטָא como el término hebreo estándar para la transgresión moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96218, 'spa', 'Hifil: hacer pecar', 'Causativo Hifil (32 ocurrencias) que introduce una estructura argumental distinta: X hace que Y peque. Pasajes clave incluyen Éxodo 23:33 (dioses extranjeros haciendo pecar a Israel), 1 Reyes 14:16 (los pecados de Jeroboam extraviando a la nación). Las glosas multilingües preservan la morfología causativa: ''hizo pecar'', ''caused to sin'', ''causa à péché''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96221, 'spa', 'Hitpael: purificarse', 'El Hitpael reflexivo (9 pasajes) expresa la autopurificación o el sometimiento a limpieza ritual, especialmente en Números 8:21 y 19:12-20 (leyes de purificación levítica). La morfología reflexiva corresponde al árabe يَتَطَهَّرُ (''purificarse a sí mismo'') y al coreano 정결해지다 (''volverse limpio''), mostrando un patrón productivo semítico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96224, 'spa', 'Participio Qal: pecador', 'Participio Qal usado sustantivamente (9 veces) que denota ''el pecador'' como categoría nominal en la literatura sapiencial (Proverbios, Eclesiastés). El árabe الخَاطِئ (''el pecador''), el coreano 죄인 (''pecador''), el suajili mwenye dhambi (''el que tiene pecado'') y el hindi पापी muestran nominalización consistente de la raíz verbal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96231, 'spa', 'Participio Qal: pecando', 'Participio Qal usado verbalmente (8 ocurrencias) que describe la acción pecaminosa en curso en posición predicativa: ''está pecando'' (1 S 14:33), ''el que peca contra'' (Pr 14:21; 19:2). El contexto lo distingue del uso sustantival; las traducciones reflejan el aspecto verbal: ''sinning'', ''pecando'', ''péchant''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96240, 'spa', 'Piel: purificar del pecado', 'El Piel (14 veces) invierte la polaridad semántica hacia la purificación: ofrecer un sacrificio expiatorio, purificar el altar (Lv 8:15), limpiar una casa de la lepra (Lv 14:49). Este uso factitivo/denominativo se deriva del sustantivo חַטָּאת (ofrenda por el pecado). El árabe طَهَّرَ (''purificar'') y el coreano 정결하게 하다 (''limpiar'') confirman el dominio de pureza ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96267, 'spa', 'errar el blanco (literal)', 'Una única ocurrencia incierta en Jueces 20:16, donde los honderos de Benjamín ''no erraban'' (לֹא יַחֲטִא), puede preservar el sentido físico original de fallar un tiro al blanco. Las traducciones divergen: ''miss'', ''erraban'', confirmando la ambigüedad sobre si se trata de puntería literal o extensión figurada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96278, 'spa', 'cargar con la pérdida', 'Génesis 31:39 presenta un uso singular: Jacob ''cargaba con la pérdida'' (אֲחַטֶּנָּה) de las ovejas robadas. La glosa ''soportaba la pérdida de ella'' sugiere un sentido comercial o jurídico de asumir responsabilidad, posiblemente relacionado con la carencia o falta del animal robado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96300, 'spa', 'hacer culpable a alguien', 'Isaías 29:21 usa un participio Hifil en una construcción inusual: ''los que hacen pecar al hombre'' (מַחֲטִיאֵי אָדָם). El contexto sugiere hacer que alguien sea tratado como culpable o inducirlo a la falta, pero el marco sintáctico es único y las traducciones difieren: ''making a man [an offender]'', ''los que hacen pecar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96307, 'spa', 'Pecado, transgresión', 'Pecado, transgresión: el sentido primario — pecado o transgresión contra la ley y el pacto de Dios. Abarca 33 de 35 ocurrencias, tanto en formas singulares como plurales con diversos sufijos pronominales. Pasajes clave incluyen Levítico 19:17 (''no llevarás pecado por causa de él''), Salmo 51:11 (''esconde tu rostro de mis pecados'') e Isaías 1:18 (''aunque vuestros pecados sean como la grana''). Todas las lenguas meta lo traducen con su vocablo central para la transgresión moral: ''pecado'' en español, ''péché'' en francés, ''Sünde'' en alemán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96323, 'spa', 'Ofrenda por el pecado', 'Ofrenda por el pecado: extensión cúltico-técnica donde חֵטְא no designa la transgresión sino el sacrificio prescrito para expiarla. En 2 Reyes 12:16, el ''dinero del pecado'' (כֶּסֶף חַטָּאת) no se llevaba al tesoro del templo. Este desplazamiento metonímico de la ofensa a la ofrenda está bien atestiguado con el sustantivo afín חַטָּאת y aparece aquí una vez con חֵטְא.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96327, 'spa', 'Falta, ofensa, error', 'Falta, ofensa, error: un sentido más leve de falta, ofensa o error — un agravio cometido contra otra persona más que una transgresión teológica grave. Deuteronomio 19:15 estipula que ''un solo testigo no bastará contra una persona por cualquier falta'' (חֵטְא), en un contexto legal de agravios humanos juzgados en tribunal. Génesis 41:9, donde el copero recuerda ''mis faltas hoy'', apunta igualmente a un ámbito interpersonal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96328, 'spa', 'Pecadores (sustantivo)', 'Pecadores (sustantivo): personas caracterizadas por pecado habitual o definitorio. Este es el uso dominante en 18 apariciones. Designa una clase moral: personas opuestas al tsaddiq (justo). Pasajes clave incluyen Génesis 13:13 (''pecadores contra Jehová''), la geografía moral del Salmo 1:1, y los oráculos proféticos contra pecadores en Sion (Is 1:28; 33:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96337, 'spa', 'Pecaminoso (adjetivo atributivo)', 'Pecaminoso (adjetivo atributivo): que describe un sustantivo como caracterizado por el pecado. Este raro uso adjetival aparece solo en Amós 9:8 — ''el reino pecador'' (hammamlakah hachattá''ah) — donde modifica a la nación misma en lugar de identificar personas individuales, marcando el cambio de etiqueta personal a caracterización nacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96340, 'spa', 'Pecado, transgresión', 'El pecado como transgresión moral, especialmente ofensa grave ante Dios. Seis de siete apariciones llevan este sentido, frecuentemente en la poderosa frase חֲטָאָה גְדֹלָה («gran pecado»). Abimelec protesta: «Has traído sobre mí un gran pecado» (Gn 20:9), Moisés confronta a Aarón por el becerro de oro con la misma frase (Éx 32:21, 30, 31), y Jeroboam «hizo pecar a Israel con un gran pecado» (2 R 17:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96341, 'spa', 'Ofrenda por el pecado', 'Una ofrenda por el pecado, el sacrificio ritual prescrito para expiar la falta. En Sal 40:6, «holocausto y ofrenda por el pecado (חֲטָאָה) no has demandado», la palabra aparece junto a עוֹלָה en un contexto que la mayoría de versiones antiguas y comentaristas interpretan como terminología sacrificial. La evidencia multilingüe lo confirma: en español «ofrenda por pecado», en inglés «sin-offering» y en alemán «Sünde-Opfer».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96344, 'spa', 'ofrenda por el pecado', 'La ofrenda por el pecado: el animal sacrificial específico o el ritual prescrito en la legislación sacerdotal para efectuar la expiación. Con 120 ocurrencias concentradas en Levítico 4-5, Números 15 y 28-29, y Ezequiel 40-46, es un término cúltico plenamente técnico. La evidencia multilingüe es decisiva: el español amplía a ''ofrenda por el pecado'', el francés a ''offrande pour le péché'' y el alemán a ''Sündopfer''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96347, 'spa', 'pecado, transgresión', 'Pecado como acto, condición u ofensa: el sentido fundamental de falta moral o transgresión contra Dios o el prójimo. Con 170 ocurrencias, es el uso mayoritario en la literatura narrativa, profética y sapiencial. Génesis 4:7 (''el pecado está agazapado a la puerta'') lo personifica; Levítico 4:3 (''si el sacerdote ungido peca'') introduce el contexto cúltico. Todas las lenguas emplean su término básico para el pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96361, 'spa', 'pecado y su castigo', 'Un pequeño grupo (3x) donde חַטָּאת aparece en contextos que funden el pecado con su castigo o consecuencia, haciendo que ''pecado'' y ''culpa/castigo'' resulten casi intercambiables. El Salmo 109:14 (''no sea borrado el pecado de su madre'') y Daniel 9:20 (''confesando mi pecado y el pecado de mi pueblo'') muestran חַטָּאת en contextos penitenciales donde el peso de la consecuencia se pone en primer plano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96381, 'spa', 'pecado como oprobio colectivo', 'Una única ocurrencia en Proverbios 14:34 (''el pecado es afrenta de las naciones'') donde חַטָּאת funciona como abstracto colectivo: el pecado como condición nacional o reproche. El contexto proverbial y sapiencial confiere a esta instancia un carácter gnómico y universal, trascendiendo la infracción individual para señalar la degradación de un pueblo entero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96398, 'spa', 'agua de purificación', 'Una ocurrencia singular en Números 8:7 donde חַטָּאת aparece en el contexto de la purificación levítica (''rociarás sobre ellos el agua de la purificación''). El español traduce ''purificación'' en vez de ''pecado'' u ''ofrenda'', situándolo en la frontera entre ofrenda por el pecado y rito de purificación. El pasaje describe la limpieza de los levitas para el servicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96439, 'spa', 'Cortar leña', 'El sentido activo Qal de cortar, talar o recoger madera, abrumadoramente leña para combustible. La forma participial חֹטְבֵי עֵצִים («cortadores de leña») es prácticamente una frase fija para el trabajo servil asignado a los gabaonitas (Jos 9:21, 23, 27), siempre emparejada con el acarreo de agua (Dt 29:11). Ezequiel 39:10 describe a Israel recogiendo leña del campo de batalla, y 2 Crónicas 2:9 enumera a los leñadores entre los obreros de Salomón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96444, 'spa', 'Tallado, esculpido (pasivo)', 'El participio pasivo Pual en Salmo 144:12 — מְחֻטָּבוֹת — pasa del tosco corte de leña a la artesanía fina: hijas «esculpidas» como columnas angulares de un palacio. La misma raíz que en otros textos describe partir troncos para el fuego evoca aquí el cincel del artesano que da forma a la piedra o la madera en algo hermoso. El español «esculpidas» capta bien esta elegancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96448, 'spa', 'Trigo como cereal cultivado y alimento básico, una de las siete especies que def', 'Trigo como cereal cultivado y alimento básico, una de las siete especies que definen la fertilidad de la tierra (Dt 8:8). Aparece en fórmulas del calendario de cosecha (Gn 30:14; Éx 34:22; Rt 2:23), como metáfora de la generosidad divina — ''la grosura del trigo'' (Dt 32:14; Sal 81:17) — y como mercancía comercial exportada a Tiro (Ez 27:17). Las glosas multilingües convergen uniformemente: español ''trigo'', francés ''blé'', alemán ''Weizen''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96454, 'spa', 'Nombre propio postexílico', 'Nombre propio postexílico portado por varios individuos: un descendiente de David (1 Cr 3:22; Esd 8:2), un constructor de la muralla de Jerusalén (Neh 3:10) y un jefe de casa sacerdotal (Neh 10:4; 12:2). En español se traduce como ''Hatús'' o ''Jatús''. Las formas de la LXX Χαττους y Αττους indican debilitamiento de la gutural inicial en griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96461, 'spa', 'Arrebatar con violencia', 'Agarrar o atrapar de manera súbita, frecuentemente con intención violenta. Jueces 21:21 lo emplea literalmente para los benjaminitas que tomaron esposas durante la fiesta en Siló. El Salmo 10:9 lo usa dos veces en una vívida metáfora, comparando al impío con un depredador al acecho que atrapa al indefenso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96463, 'spa', 'fórmula de juramento', 'Fórmula de juramento y adjuración: ''¡vive X!'' (חַי יהוה, חַי אֲנִי, חַי נַפְשֶׁךָ) — 87 ocurrencias concentradas en la historia deuteronomista (Jueces a Reyes) y los Profetas. Funciona como el juramento más solemne posible, empeñando la palabra sobre la vida inviolable de Dios. Aparece por primera vez en Rut 3:13 (Booz jurando por la vida del SEÑOR) y luego se torna casi formulaica en los relatos proféticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96464, 'spa', 'vivo, viviente', 'Sentido adjetival central: vivo, viviente, que posee vida — 146 de 244 ocurrencias. Se emplea predicativamente (''¿Vive aún vuestro padre?'', Gn 43:7), atributivamente (''el Dios vivo'', Dt 5:26; Jos 3:10; 1 S 17:26) y sustantivado (''la tierra de los vivientes'', Sal 27:13; Is 38:11). Abarca todo el espectro biológico-teológico: desde el alivio de Jacob al saber que José vive (Gn 45:26) hasta la confesión de fe en el Dios que da vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96477, 'spa', 'ser viviente, animal', 'Uso sustantivado: un ser viviente, criatura o animal — 8 ocurrencias donde חַי funciona como sustantivo concreto. Dios otorga a Adán dominio sobre todo ser viviente (Gn 1:28), Eva recibe el nombre de ''madre de todos los vivientes'' (Gn 3:20) y Noé introduce todo חַי en el arca (Gn 6:19). El paso de adjetivo a sustantivo se confirma por el cognado árabe حَيَوَان, un lexema diferenciado para ''animal''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96489, 'spa', 'crudo, fresco', 'Sentido físico extendido: crudo, fresco, sin cocer — 2 ocurrencias donde חַי describe el estado de la carne o del material en lugar de vida animada. En 1 S 2:15 los sacerdotes corruptos exigen carne cruda en vez de cocida, y en Sal 58:10 las espinas son barridas ''ya crudas, ya encendidas'' (significado discutido). El árabe نَيِّء (''crudo'') selecciona este mismo campo semántico alimentario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96497, 'spa', '¿vivirá? (caso límite)', 'Una única ocurrencia en 2 S 12:22, donde חַי aparece en la súplica de David: ''¿Quién sabe si el niño vivirá?'' La forma adjetival, contigua al verbo, puede representar un caso fronterizo entre el sentido adjetival simple (''vivo'') y un matiz verbal-resultativo (''llegará a vivir''). Las versiones multilingües — español ''vivirá'', francés ''fera vivre'' — recurren a formas verbales más que adjetivales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96507, 'spa', 'bestia salvaje, animal', 'Sentido zoológico general de animal salvaje o bestia, especialmente en construcciones como חַיַּת הַשָּׂדֶה (''bestia del campo'') y חַיַּת הָאָרֶץ (''bestia de la tierra''). Con 79 ocurrencias es el uso dominante, abarcando desde la serpiente en el Edén (Gn 3:1) hasta las advertencias proféticas sobre bestias que devoran la tierra (Ez 14:15). El árabe وَحْش y el español ''bestia/animal'' lo traducen uniformemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96510, 'spa', 'criatura viviente visionaria', 'Las ''criaturas vivientes'' sobrenaturales de las visiones de Ezequiel — los seres de cuatro rostros y cuatro alas que sostienen el trono divino (Ez 1:5, 13-14; Ez 10). Aunque la palabra hebrea es idéntica al término zoológico común, el contexto visionario transforma por completo su significado. El español ''seres vivientes'' y el coreano saengmul (''entidad viviente'') marcan este desplazamiento semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96517, 'spa', 'vida, vitalidad', 'Sentido abstracto de ''vida'' o ''vitalidad'', que aparece principalmente con sufijos posesivos — ''su vida'', ''mi vida'' — en textos poéticos y sapienciales, sobre todo en Job 33:18-28, donde la palabra se repite en el contexto de Dios preservando la vida de una persona del abismo. El árabe حَيَاة (vida), forma nominal completamente distinta de حَيَوَان (animal), distingue con nitidez este sentido abstracto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96539, 'spa', 'apetito, voracidad', 'Una única ocurrencia en Job 38:39, donde la palabra aparece en un contexto que sugiere ''apetito'' o ''voracidad'' de la leona — ''¿Puedes saciar el apetito de los leoncillos?'' Este uso hapax probablemente representa una extensión especializada del sentido ''vitalidad/fuerza vital'' aplicado al hambre depredadora, aunque algunos lexicógrafos lo subsumen bajo el sentido zoológico general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96559, 'spa', 'Banda o comunidad', 'Banda, tropa o comunidad —un grupo de familias aliadas que actúan juntas, o un rebaño asentado bajo el cuidado divino. En 2 Samuel 23:11, 13, describe una partida filistea acampada como banda militar. En el Salmo 68:10, la imagen se torna pastoral: la congregación de Dios habita en la bondad que él preparó. El Salmo 74:19 lo usa en una súplica para que Dios no entregue a su comunidad a las fieras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96560, 'spa', 'vida, duración de vida', 'El concepto abstracto de vida, duración de vida o estado de estar vivo — abarcando la existencia física, su extensión y su calidad. Aparece 145 veces en marcos diversos: ''aliento de vida'' (Gn 2:7; 7:15), ''años de la vida de Sara'' (Gn 23:1), ''mi vida es amarga'' (Gn 27:46) y ''tu misericordia es mejor que la vida'' (Sal 63:4). Las glosas multilingües convergen enfáticamente: español ''vida/la vida'', árabe حَيَاة, francés ''vie''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96594, 'spa', 'los vivientes', 'Uso sustantivado que significa ''los vivientes'' o ''los que viven'', refiriéndose a la comunidad de quienes están vivos y no al concepto abstracto de la vida misma. Atestiguado dos veces: Salmo 66:9 (''mantiene nuestra alma entre los vivientes'') y Ezequiel 7:13 (la visión no retornará a nadie entre los vivientes). El español ''en los vivos'' capta el sentido concretizado y comunitario que lo distingue de la acepción abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96601, 'spa', 'Viviente (adjetivo)', 'Uso adjetival que significa ''viviente, vivo'', aplicado tanto a Dios como a los seres humanos. Como epíteto divino en Daniel 6:20 y 6:26, declara a Dios como ''el Dios viviente'', en paralelo con el hebreo אֵל חַי. En Daniel 2:30 y 4:17 aparece sustantivado para referirse a ''los vivientes'', es decir, aquellos que están vivos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96603, 'spa', 'Vida (sustantivo)', 'Uso nominal que significa ''vida'' o ''tiempo de vida'', funcionando como plural abstracto. En Esdras 6:10 aparece en la frase constructa ''por la vida del rey'', denotando duración y bienestar. En Daniel 7:12 se refiere a una prolongación de vida concedida a las bestias. El paso de adjetivo a sustantivo abstracto sigue el patrón hebreo donde el plural חַיִּים regularmente significa ''vida''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96606, 'spa', 'Vivir, estar vivo', 'Vivir, estar vivo, usado en el imperativo Pe''al como saludo cortesano formulaico: ''¡Oh rey, vive para siempre!'' Atestiguado cinco veces en Daniel (2:4; 3:9; 5:10; 6:6; 6:21), siempre dirigido a un monarca reinante. Los equivalentes en distintas lenguas (''vive'' en español, ''live'' en inglés) reflejan la naturaleza universal de este deseo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96607, 'spa', 'Dejar vivir, preservar', 'Mantener con vida, dejar vivir, en la conjugación Hafel (causativa). En Dan 5:19, Nabucodonosor poseía poder absoluto sobre la vida y la muerte: ''a quien quería, dejaba vivir''. El español ''dejaba vivir'' expresa con claridad la aterradora discrecionalidad del soberano sobre la supervivencia humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96609, 'spa', 'Enigma, dicho enigmático', 'Enigma, dicho enigmático: expresión oscura o desconcertante que requiere interpretación. Abarca acertijos literales (el desafío nupcial de Sansón, Jue 14:12-19), pruebas de sabiduría (los enigmas de la reina de Sabá a Salomón, 1 R 10:1; 2 Cr 9:1), alegorías proféticas (Ez 17:2; Hab 2:6), modos oscuros de comunicación divina contrastados con el habla directa (Núm 12:8), y dichos oscuros de la literatura sapiencial que sondean los misterios morales más profundos de la vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96617, 'spa', 'Qal: vivir, estar vivo', 'El sentido más amplio y frecuente (177 ocurrencias): vivir, estar vivo, continuar en existencia. Las genealogías de Génesis (''y vivió Adán novecientos treinta años'', Gn 5:5) y las promesas del pacto (''para que viváis'', Dt 30:16) ejemplifican este significado básico y no marcado de la conjugación Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96619, 'spa', 'Piel: vivificar, dar vida', 'Piel intensivo-causativo (30 ocurrencias): revivir, devolver la vida, vivificar. El cántico de Ana (''el SEÑOR mata y da vida'', 1 S 2:6) y la declaración teológica de Dt 32:39 definen esta acepción como prerrogativa exclusivamente divina — solo Dios vivifica. El español ''vivificar'' y el árabe أَحْيَا captan con precisión la fuerza causativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96625, 'spa', 'Hifil: mantener con vida', 'Hifil causativo (25 ocurrencias): mantener con vida, preservar de la muerte, salvar la vida. El mandato del arca de Noé (''para mantenerlos con vida'', Gn 6:19-20) y la revelación de José (''Dios me envió para preservar la vida'', Gn 45:7) sitúan este sentido en las grandes narrativas de la historia de salvación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96640, 'spa', 'Piel: dejar vivir, perdonar', 'Piel con matiz permisivo o preservativo (25 ocurrencias): dejar con vida, perdonar la vida, mantener vivo por decisión deliberada. Se distingue del sentido 2 por enfatizar la decisión de no matar. La desobediencia de las parteras ante Faraón (Éx 1:17-18) y el plan de las hijas de Lot (Gn 19:32, 34) son pasajes clave donde la agencia moral queda en primer plano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96647, 'spa', 'Qal: sanar, recuperarse', 'Qal con referencia específica a la recuperación de una enfermedad (6 ocurrencias): sanar, ser restaurado a la salud. La ansiosa pregunta de Ezequías ''¿Sanaré?'' (2 R 8:8-9) y su curación efectiva (2 R 20:7) anclan este sentido en las narrativas de enfermedad real. El árabe شَفِيَ (''ser sanado'') y el suajili -pona (''recuperarse'') aíslan un registro médico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96663, 'spa', 'Qal: revivir, resucitar', 'Qal que denota revivir de un estado semejante a la muerte (2 ocurrencias): volver a la vida, resucitar. El espíritu de Jacob ''revivió'' al oír que José estaba vivo (Gn 45:27), y Sansón revivió después de que Dios hendiera la peña en Lehi (Jue 15:19) — ambos son momentos de restauración inesperada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96729, 'spa', 'uso idiomático disputado', 'Una única ocurrencia controvertida en Ez 13:18, donde el objeto no es la vida física sino posiblemente las almas atrapadas por falsas profetisas. El español ''para vosotras'' se aparta del vocabulario habitual de vida, lo que sugiere que el verbo puede funcionar idiomáticamente o que el texto preserva una construcción inusual vinculada al discurso sobre hechicería.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96741, 'spa', 'Bestia, animal (arameo)', 'Bestia, animal (arameo): sustantivo arameo (חֵיוָא / חֵיוָה) que significa ''bestia'' o ''animal'', abarcando tanto fauna literal como criaturas apocalípticas simbólicas. En Daniel 4 se refiere a las bestias del campo bajo cuya sombra habitó Nabucodonosor durante su locura; en Daniel 7 designa las cuatro bestias visionarias que representan imperios mundiales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96748, 'spa', 'Vivir, estar vivo', 'Vivir, estar vivo: forma Qal de חָיָה — vivir, estar vivo, permanecer con vida o seguir viviendo. Cubre la vida biológica (Gn 5:5, períodos de vida patriarcales), la advertencia divina sobre los límites del encuentro mortal con Dios (Éx 33:20, ''no me verá hombre y vivirá''), y las promesas proféticas de supervivencia mediante la obediencia (Jer 21:9; 38:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96757, 'spa', 'Ejército, fuerza militar', 'Ejército, fuerza militar: un ejército, fuerza militar o cuerpo organizado de tropas — soldados reunidos para la guerra o enviados en campaña. Este sentido dominante (11 apariciones) surge en narrativas históricas: Tou, rey de Hamat, envía a su hijo a David ''con todo su ejército'' (2 Sam 8:9; 1 Cr 18:9), Senaquerib envía a su comandante ''con gran ejército'' contra Jerusalén (2 R 18:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96759, 'spa', 'Muralla, fortificación', 'Muralla, fortificación: una muralla, baluarte o muro de fortificación exterior que rodea una ciudad o fortaleza. Seis apariciones se concentran en textos poéticos y proféticos: Joab asedia Abel y golpea ''la muralla'' (2 Sam 20:15), Isaías declara que Dios ''pondrá salvación por muros y baluarte'' (Is 26:1), Lamentaciones llora que el Señor ''hizo que muralla y muro se lamentaran'' (Lam 2:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96768, 'spa', 'Fuerza, poder, vigor', 'Fuerza, poder, vigor: fuerza o poder en sentido abstracto o general — la potencia bruta detrás de ejércitos y murallas. Dos apariciones preservan este significado raíz: Joab sacando ''la fuerza del ejército'' al comienzo del año (1 Cr 20:1), y el enigmático Salmo 10:10, donde los indefensos ''caen por su fuerza''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96771, 'spa', 'Dolor, angustia, parto', 'Dolor convulsivo, angustia o dolores de parto: sufrimiento físico o emocional intenso. En el Éxodo, los pueblos se retorcían de temor (Éx 15:14). Reyes aliados que atacaban Jerusalén se estremecieron ''como mujer de parto'' (Sal 48:6). Sion se retuerce ante Asiria (Miq 4:9), y tanto Judá como Babilonia sufren angustias comparadas con el alumbramiento (Jer 6:24; 50:43).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96776, 'spa', 'valor, valentía bélica', 'Valor marcial, proeza o coraje heroico — la cualidad del guerrero más que la fuerza colectiva. Se halla en la construcción אִישׁ חַיִל (''hombre de valor'', Jue 18:2; 1 S 9:1) y en la frase עָשָׂה חַיִל (''actuar valerosamente'', Nm 24:18; Sal 60:14). El español distingue ''valor'' de ''ejército'', marcando esta acepción como cualitativa en vez de colectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96777, 'spa', 'ejército, fuerza militar', 'Una fuerza militar organizada: ejército, tropas, hueste. El sentido más frecuente (99 ocurrencias), presente en toda la narrativa y la profecía. El חַיִל de Faraón perece en el mar (Éx 14:28), Josué reúne el חַיִל de Israel para Hai (Jos 8:3) y los profetas anuncian la destrucción de חַיִלוֹת (ejércitos) extranjeros. El árabe جيش y el español ''ejército'' lo traducen uniformemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96784, 'spa', 'riqueza, bienes', 'Riqueza, bienes, posesiones materiales. La capacidad económica de una persona o comunidad (Gn 34:29; Dt 8:17-18; Job 5:5). El árabe ثروة y el español ''riqueza'' convergen en el sentido financiero. Teológicamente cargado en Deuteronomio 8:18, donde Dios ''te da el poder para producir חַיִל (riqueza)'', vinculando la abundancia económica a la provisión divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96786, 'spa', 'fuerza, poder', 'Fuerza física o abstracta, poder, potencia — la energía bruta ejercida por una persona, un caballo o Dios. Se encuentra especialmente en la poesía (Sal 18:33, 40; Sal 33:17; Hab 3:19). El árabe قوة y el español ''fuerza/poder'' marcan consistentemente esta acepción como capacidad pura, distinta de tropas organizadas o valentía personal. En 2 S 22:33, 40 es Dios quien ''me ciñe de חַיִל''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96791, 'spa', 'capacidad, virtud', 'Competencia moral o práctica, habilidad, excelencia, virtud. La acepción más rara pero de mayor resonancia cultural, visible en la אֵשֶׁת חַיִל (''mujer virtuosa'', Pr 31:10, 29) y en el consejo de Jetro de elegir ''hombres capaces'' (אַנְשֵׁי חַיִל, Éx 18:21, 25). El alemán ''Tüchtigkeit'' (capacidad) y el español ''virtud'' la distinguen del valor marcial. Génesis 47:6 la emplea para la competencia profesional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96859, 'spa', 'Poder, fuerza', 'Poder físico o político, fuerza y vigor. En Esdras 4:23 la expresión pareada ''con fuerza y poder'' describe la compulsión coercitiva para detener la construcción. En Daniel 3:4 y 5:7, el uso adverbial בְּחַיִל significa ''con poder'' o ''a gran voz'', indicando intensidad de acción. En Daniel 3:20 se combina con גִּבָּרִין para describir hombres de fuerza excepcional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96860, 'spa', 'Ejército, hueste militar', 'Una fuerza militar, ejército o hueste de soldados. En Daniel 3:20 חַיִל se refiere al contingente armado de Nabucodonosor, y en Daniel 4:35 la frase חֵיל שְׁמַיָּא (''ejército del cielo'') designa la hueste celestial, en paralelo con el hebreo צְבָא הַשָּׁמַיִם. Esta acepción colectiva militar se distingue claramente del uso abstracto de ''poder''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96869, 'spa', 'El adjetivo espacial que señala lo que se encuentra en el exterior de una estruc', 'El adjetivo espacial que señala lo que se encuentra en el exterior de una estructura, opuesto a penimi (''interior''). Predomina en el plano del templo de Ezequiel, donde ''el atrio exterior'' (hachatsér hachitsonah) aparece más de veinte veces para definir la zona de acceso público del santuario escatológico (Ez 10:5; 40:17, 20, 31; 42:1-14; 44:19; 46:21). También describe la entrada exterior del rey en el Templo de Jerusalén (2 R 16:18), el muro exterior de Manasés alrededor de la Ciudad de David (2 Cr 33:14) y el atrio exterior del palacio de Asuero (Est 6:4). En 1 Reyes 6:29-30 distingue la sala exterior del santuario interior de Salomón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96876, 'spa', 'Seno, regazo, abrazo', 'Seno, regazo, abrazo: el área del pecho, regazo o seno como lugar de intimidad, protección y ocultamiento. Se usa para cargar niños (Nm 11:12; Is 40:11), el abrazo conyugal (Pr 5:20; Dt 13:6), esconder objetos en el pliegue del vestido (Éx 4:6-7; Pr 16:33; 21:14) y como metáfora del cuidado íntimo de Dios. La expresión «esposa de tu seno» aparece en múltiples idiomas como símbolo de cercanía matrimonial profunda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96890, 'spa', 'Base o repisa del altar', 'Base o repisa del altar: la base, repisa inferior o cavidad del altar en la visión del templo de Ezequiel (Ez 43:13, 14, 17; también el piso del carro en 1 R 22:35). Una extensión arquitectónica del aspecto de «cavidad» o «hueco» del concepto de seno. Las traducciones distinguen claramente este uso del sentido corporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96905, 'spa', 'Nombre propio fenicio portado por tres figuras bíblicas distintas', 'Nombre propio fenicio portado por tres figuras bíblicas distintas. El más prominente es Hiram, rey de Tiro, el aliado que proveyó a Salomón de madera de cedro del Líbano, oro y experiencia marítima para el Templo y el palacio (2 S 5:11; 1 R 5:1-12; 9:11-14; 10:22). En segundo lugar, un artesano broncista de ascendencia mitad tiria, mitad israelita, enviado por el rey para fundir la gran obra metálica del Templo: los pilares, el mar de bronce y las fuentes (1 R 7:13-45; 2 Cr 2:12; 4:11-16). Crónicas menciona además un tercer Hiram entre los hijos de Benjamín (1 Cr 8:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96911, 'spa', 'Paladar, órgano del gusto', 'Paladar, órgano del gusto: el cielo de la boca como órgano físico del gusto, usado literalmente para discernir sabores y metafóricamente para evaluar verdad o sabiduría. Job 12:11 y 34:3 establecen el paladar como sede del discernimiento — así como prueba la comida, el oído prueba las palabras. Lamentaciones 4:4 describe la lengua del niño pegada a su paladar por la sed.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96916, 'spa', 'Boca, órgano del habla', 'Boca, órgano del habla: la boca o paladar usado metonímicamente para el habla y la expresión verbal, enfatizando lo que sale de la boca más que lo que se saborea. Cantar de los Cantares 5:16 alaba el paladar del amado como ''dulcísimo'', y 7:9 lo compara con buen vino — aquí el enfoque está en las palabras habladas, no en la sensación gustativa. Oseas 8:1 ordena ''¡trompeta a tu paladar!'', donde el paladar representa la boca que proclama.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96925, 'spa', 'Esperar, aguardar', 'Esperar paciente o expectantemente a alguien o algo, típicamente con una actitud de esperanza, confianza o anticipación. El participio Qal en Isaías 30:18 describe a quienes ''esperan en'' el Señor, mientras que en Job 3:21 el desesperado ''esperar la muerte'' invierte la esperanza pero conserva la postura expectante. Daniel 12:12 pronuncia bienaventurado al que espera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96937, 'spa', 'Acechar, emboscar', 'Acechar con intención hostil, al acecho en emboscada para atacar. Esta única aparición en Oseas 6:9 reutiliza llamativamente el verbo de espera paciente transformándolo en violencia depredadora: los sacerdotes son comparados con bandas de salteadores (גְּדוּדִים) que ''acechan'' en el camino a Siquem. El español ''acechadores'' y el cambio contextual de espera esperanzada a hostil lo marcan como un sentido distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96939, 'spa', 'Anzuelo de pesca', 'Anzuelo o instrumento similar para la captura. Job 41:1 plantea la pregunta retórica de sacar al Leviatán con un anzuelo, destacando su imposibilidad. Isaías 19:8 menciona a pescadores que lanzan anzuelos al río durante la sequía de Egipto. Habacuc 1:15 describe a los babilonios sacando a toda la humanidad con anzuelos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96940, 'spa', 'Colina de Haquilá', 'La colina de Haquilá, un accidente geográfico en el desierto de Zif. 1 Samuel 23:19 y 26:1 recogen a los zifeos informando sobre la ubicación de David «en la colina de Haquilá», mientras que 26:3 describe a Saúl acampando allí durante su persecución. En hebreo siempre lleva el artículo (הַחֲכִילָה), tratándolo como un topónimo definido y bien conocido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96941, 'spa', 'Sabios, eruditos', 'Sustantivo plural arameo que designa la clase profesional de sabios en las cortes reales babilónica y persa, quienes poseían erudición esotérica y servían como consejeros reales junto a magos y astrólogos (Daniel 2:12-14, 18, 24, 27; 4:3; 5:7-8, 15). El decreto de Nabucodonosor de destruir a todos los sabios de Babilonia (Daniel 2:12-13) y la posterior vindicación de Daniel entre ellos forman el arco dramático central.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96948, 'spa', 'El sentido central del Qal', 'El sentido central del Qal: ser o volverse sabio, actuar con sabiduría, abarcando exhortaciones imperativas, declaraciones narrativas y observaciones proverbiales sobre la adquisición de sabiduría. Salomón ''fue más sabio que todos los hombres'' (1 R 4:31); la hormiga enseña al perezoso a ''ser sabio'' (Pr 6:6); el compañero de los sabios ''se hará sabio'' (Pr 13:20). El Qal atrae vocabulario de carácter personal que apunta a un estado interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96952, 'spa', 'El causativo Piel e Hifil', 'El causativo Piel e Hifil: hacer sabio a alguien, impartir o enseñar sabiduría. Los testimonios de Dios ''hacen sabio al sencillo'' (Sal 19:7); Job protesta que Dios ''nos hace más sabios que las bestias'' (Job 35:11); José fue enviado para ''enseñar sabiduría'' a los ancianos de Egipto (Sal 105:22). El cambio hacia un lenguaje pedagógico es consistente en todas las lenguas, confirmando una función semántica genuinamente distinta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96955, 'spa', 'El Pual pasivo', 'El Pual pasivo: ser hecho sabio o hábil, describiendo a alguien que ha sido dotado de sabiduría o pericia por un agente externo. Las ''criaturas pequeñas'' de Proverbios 30:24 son ''hechas sabias'' (mechukamim) por instinto; el ''encantador astuto'' de Salmo 58:5 se describe como alguien expertamente adiestrado. La morfología pasiva confirma este sentido como la contraparte pasiva genuina del Piel causativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96957, 'spa', 'El Hitpael reflexivo', 'El Hitpael reflexivo: hacerse sabio a sí mismo, mostrarse sabio — una sola aparición cautelar en Eclesiastés 7:16: ''No te hagas demasiado sabio.'' La raíz reflexiva añade una cualidad performativa y autodirigida: sabiduría buscada por exhibición o autopromoción en lugar de sabiduría recibida de Dios o adquirida por experiencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96967, 'spa', 'El Hitpael cohortativo con matiz astuto o maquinador', 'El Hitpael cohortativo con matiz astuto o maquinador: actuar con astucia, obrar con sagacidad calculadora. En Éxodo 1:10, Faraón dice ''Vamos, actuemos sabiamente contra ellos'', donde ''sabiamente'' lleva el tono siniestro de opresión calculada. El Hitpael aquí no es automejora reflexiva sino conspiración colectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96972, 'spa', 'sabio, prudente', 'Describe a una persona que posee sabiduría, discernimiento o prudencia como cualidad moral e intelectual — el uso adjetival básico con 84 ocurrencias. En Dt 4:6 la observancia de la Torá hará que las naciones digan: ''Ciertamente este gran pueblo es sabio y entendido.'' En 2 S 13:3 Jonadab es descrito como ''muy sabio'' (חָכָם מְאֹד), aunque su consejo resulta moralmente perverso — recordatorio de que la astucia no equivale a rectitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96973, 'spa', 'sabios, eruditos (variante)', 'Variante sustantivada del sentido 2, que designa la clase profesional de sabios y consejeros. Incluye las 48 ocurrencias donde חֲכָמִים funciona como título social — los sabios de Egipto (Gn 41:8), los sabios convocados por reyes (Éx 7:11), y el estamento sapiencial mencionado en Jeremías 18:18 junto al sacerdocio y la profecía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96991, 'spa', 'mujeres sabias', 'Uso sustantivo femenino que se refiere a las mujeres sabias como categoría social reconocida — 2 ocurrencias. En Jue 5:29 ''las más sabias de sus damas'' (חַכְמוֹת שָׂרוֹתֶיהָ) responden a la madre de Sísara, mientras que en Jer 9:17 las ''mujeres hábiles'' (חֲכָמוֹת) son plañideras profesionales convocadas para entonar el canto fúnebre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (96994, 'spa', 'diestro, artesano experto', 'Habilidad técnica o pericia artesanal más que sabiduría moral — 3 ocurrencias concentradas en la construcción del templo según el Cronista. En 2 Cr 2:7 Salomón pide un hombre ''diestro'' (חָכָם) en trabajar oro, plata, bronce y hierro; en 2 Cr 2:14 se describe a Hiram-abí como ''experto'' en múltiples oficios. Los textos del tabernáculo en Éxodo (Éx 28:3; 31:6; 35:10, 25) emplean la misma raíz para la destreza manual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97003, 'spa', 'sabiduría, discernimiento', 'La cualidad intelectual y moral amplia de sabiduría, discernimiento y buen juicio — 146 de 149 ocurrencias. Abarca desde la legendaria perspicacia de Salomón en gobierno e historia natural (1 R 4:29-34), pasando por la instrucción ética de Proverbios (Pr 1:2, 7; 9:10), hasta la interrogación filosófica de Eclesiastés sobre el valor de la sabiduría (Ecl 1:13, 16-18). El español ''sabiduría'', el árabe حكمة y el francés ''sagesse'' convergen en este núcleo moral-intelectual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97020, 'spa', 'consejo prudente, sagacidad', 'Consejo prudente o sabiduría estratégica aplicada en una crisis concreta — representado por la mujer sabia de Abel Bet-Maacá en 2 Samuel 20:22, quien ''con su sabiduría'' persuadió al pueblo para poner fin al asedio de Joab entregando la cabeza de Seba. Esta ocurrencia tiende un puente entre la cualidad abstracta (sentido 1) y la habilidad práctica (sentido 2): no es conocimiento teórico ni destreza manual, sino perspicacia situacional aplicada con eficacia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97029, 'spa', 'habilidad, artesanía', 'Habilidad técnica, artesanía o pericia manual — el saber práctico aplicado a un oficio concreto. Las narraciones de la construcción del tabernáculo en Éxodo muestran vívidamente este sentido: los obreros diestros son llenados de חָכְמָה para diseñar obras artísticas en metal, piedra y tela (Éx 28:3; 31:3, 6; 35:26, 31, 35; 36:1-2). Primera Crónicas 28:21 extiende el patrón a la edificación del Templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97032, 'spa', 'Sabiduría', 'La sabiduría como discernimiento y comprensión otorgados por Dios, cognado arameo del hebreo חָכְמָה. El español la traduce consistentemente como «sabiduría» y el inglés como «wisdom». El término funciona en tres registros afines: como atributo divino (Dn 2:20), como don revelador que permite interpretar sueños y misterios (Dn 2:21, 23, 30; 5:11, 14), y como competencia administrativa para ejercer justicia (Esd 7:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97038, 'spa', 'Sabiduría plena', 'Sabiduría en su sentido hebreo más pleno: personificada como mujer que proclama públicamente (Prov 1:20; 9:1), inaccesible para los necios (Prov 24:7) y ejercida con sentido práctico por mujeres sabias (Prov 14:1). El plural חָכְמוֹת en Sal 49:3 y Proverbios resalta el carácter multifacético. Las traducciones principales convergen en un solo término, reflejando su riqueza semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97039, 'spa', 'Profano, común', 'Lo que es profano, común o no consagrado — el opuesto conceptual de קֹדֶשׁ (santo). Este término define uno de los polos de la distinción sacerdotal fundamental entre lo sagrado y lo ordinario, distinción que los sacerdotes tenían el encargo de enseñar al pueblo (Lv 10:10; Ez 44:23). La visión del templo de Ezequiel utiliza esta categoría arquitectónicamente para separar el espacio santo del terreno común (42:20; 48:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97045, 'spa', 'Herrumbre profética', 'Herrumbre o inmundicia incrustada en una olla metálica, utilizada exclusivamente en Ez 24:6-12 como símbolo profético de la culpa de sangre irremovible de Jerusalén. Aparece cinco veces en un solo oráculo, intensificando la imagen de una ciudad cuya impureza no puede eliminarse. La raíz vinculada a ''estar enfermo'' refuerza la dualidad físico-metafórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97047, 'spa', 'grasa, sebo', 'grasa, sebo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97051, 'spa', 'lo mejor, la parte más selecta', 'lo mejor, la parte más selecta');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97071, 'spa', 'Leche', 'Leche: el sentido primario y ampliamente dominante: leche fresca como alimento y símbolo de fertilidad y provisión divina. Aparece en las narrativas patriarcales (Gn 18:8) y permea el vocabulario del pacto mediante la frase «tierra que fluye leche y miel». La distinción con חֶמְאָה (cuajada/mantequilla) se mantiene cuidadosamente en la poesía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97078, 'spa', 'Queso, cuajada', 'Queso, cuajada: un sentido lácteo especializado que designa queso o producto de leche cuajada, atestiguado en 1 S 17:18 donde David lleva «diez porciones de queso» al jefe del ejército. Las glosas multilingües divergen aquí de modo instructivo: el inglés traduce «the cheese» mientras que el español retiene «la leche».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97080, 'spa', 'Lactante, cría de leche', 'Lactante, cría de leche: un uso metonímico que designa un lactante o cría que aún mama, literalmente «uno de leche», atestiguado en 1 S 7:9, donde Samuel ofrece un cordero de leche como holocausto. El español «de leche» capta la metonimia directamente, tratando la sustancia como marcador de la etapa de desarrollo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97083, 'spa', 'Juram (nombre propio)', 'Juram (nombre propio): un nombre propio aparentemente no relacionado, Juram (o Churam), que aparece en 2 Cr 4:11 en referencia al artesano tirio. Las glosas multilingües confirman que se trata como nombre personal y no como sustantivo común. Su coincidencia homográfica con la palabra para leche es probablemente casual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97087, 'spa', 'Duración mortal', 'Duración de la vida, lapso vital, existencia mortal. Usado en Job 11:17 y Sal 39:5 (paralelo a ''mis días'') para expresar la brevedad de la existencia humana. El cognado árabe khuldun (''duración perpetua'') revela un contraste irónico: la raíz porta eternidad, pero en hebreo enfatiza la finitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97092, 'spa', 'estar enfermo, enfermar', 'estar enfermo, enfermar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97094, 'spa', 'debilitarse, perder fuerzas', 'debilitarse, perder fuerzas');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97096, 'spa', 'ser dañino, ser angustioso', 'ser dañino, ser angustioso');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97097, 'spa', 'ser grave, ser incurable', 'ser grave, ser incurable');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97098, 'spa', 'ser herido (pasivo)', 'ser herido (pasivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97099, 'spa', 'estar débil (Nifal)', 'estar débil (Nifal)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97100, 'spa', 'agotarse, extenuarse', 'agotarse, extenuarse');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97101, 'spa', 'fingir enfermedad, simular estar enfermo', 'fingir enfermedad, simular estar enfermo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97105, 'spa', 'hacer enfermar, causar enfermedad', 'hacer enfermar, causar enfermedad');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97117, 'spa', 'afligirse, sufrir dolor', 'afligirse, sufrir dolor');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97130, 'spa', 'Suplicar, buscar favor', 'Suplicar, buscar favor: suplicar, apaciguar o buscar fervientemente el favor de alguien, literalmente ''hacer dulce el rostro'' (Piel de chalah II con penei). Casi siempre dirigido a YHWH en momentos de crisis: Moisés tras el becerro de oro (Éx 32:11), el profeta en Betel por la mano de Jeroboam (1 R 13:6), Ezequías durante su enfermedad (2 Cr 33:12), y Daniel en el exilio (Dan 9:13). Zacarías 7:2 y 8:21-22 vislumbran naciones viniendo a suplicar el favor de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97145, 'spa', 'Torta, pan perforado', 'Un tipo de torta o pan, probablemente perforado o en forma de anillo (de la raíz חלל, ''perforar, horadar''), preparado exclusivamente para uso sacrificial y ritual. Las variedades incluyen: tortas sin levadura mezcladas con aceite para la ofrenda de cereal (Levítico 2:4; 7:12), tortas de flor de harina para el pan de la Presencia (Levítico 24:5), ofrendas de primicias de masa (Números 15:20) y pan de consagración sacerdotal (Éxodo 29:2, 23; Levítico 8:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97154, 'spa', 'sueño, visión nocturna', 'sueño, visión nocturna');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97174, 'spa', 'Ciudad judeomabita', 'Nombre de ciudad que aparece tanto en contexto judaíta como moabita. Josué 15:51 la incluye entre las ciudades de la serranía de Judá, mientras que Josué 21:15 la designa como ciudad levítica (equivalente a Hilén en 1 Crónicas 6:43). Jeremías 48:21 menciona una Holón moabita en un oráculo de juicio. Las transliteraciones interlingüísticas mantienen el nombre como topónimo propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97175, 'spa', 'Ventana, abertura en el muro', 'Ventana, abertura en el muro: una abertura en un muro para luz, ventilación y observación, usada en arquitectura doméstica, militar y sagrada. Las ventanas narrativas sirven como puntos focales dramáticos: la ventana del arca de Noé (Gn 8:6), la vía de escape de Rajab (Jos 2:15), Mical observando a David (2 S 6:16), la aparición fatal de Jezabel (2 R 9:30). En las visiones del templo de Ezequiel (40:16-46:2), la palabra se convierte en un término arquitectónico técnico para ventanas que se estrechan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97189, 'spa', 'Distrito de exilio', 'Territorio bajo control asirio que sirvió como destino para los israelitas deportados. 2 Reyes 17:6 y 18:11 describen deportaciones idénticas «a Jalaj y Jabor», mientras que 1 Crónicas 5:26 incluye a Jalaj entre los lugares de exilio de las tribus transjordanas. La preposición לְ (a/en) acompaña habitualmente al nombre, indicando dirección o ubicación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97191, 'spa', 'Angustia convulsiva', 'Angustia o dolor convulsivo, una aflicción severa que atenaza los lomos. En Isaías 21:3, los lomos del profeta se llenan de חַלְחָלָה al recibir el aterrador oráculo contra Babilonia, manifestación física de la carga profética. En Nahúm 2:10, la caída de Nínive produce esta misma angustia en cada rostro y cada cintura. Ezequiel 30:4, 9 la extiende a Egipto y Etiopía bajo el juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97195, 'spa', 'Enfermedad, dolencia o padecimiento físico que afecta a individuos o comunidades', 'Enfermedad, dolencia o padecimiento físico que afecta a individuos o comunidades. Aparece en contextos de pacto para las plagas que Dios infligirá o retendrá (Dt 7:15; 28:59, 61), y en la narrativa para aflicciones específicas: la enfermedad mortal del hijo de la viuda en Sarepta (1 R 17:17), la lesión de Ocozías (2 R 1:2), la enfermedad terminal de Eliseo (2 R 13:14) y los pies enfermos de Asa (2 Cr 16:12). Alcanza su profundidad teológica en Isaías 53:3-4, donde el Siervo Sufriente es descrito como ''conocedor de enfermedad'' que ha llevado ''nuestras dolencias''. Oseas 5:13 lo extiende metafóricamente a la enfermedad espiritual de una nación descarriada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97210, 'spa', 'Flauta, caramillo', 'Flauta o caramillo — instrumento de viento para ocasiones tanto gozosas como luctuosas. Se usa en la descripción de bandas proféticas (1 Sam 10:5), las festividades de coronación de Salomón (1 Re 1:40), la crítica de Isaías a los banquetes (Is 5:12) y una procesión de peregrinaje jubilosa (Is 30:29). Jeremías 48:36 invierte su tono al usarlo como imagen del lamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97214, 'spa', 'Interjección que expresa vehemente repudio moral o religioso', 'Interjección que expresa vehemente repudio moral o religioso: ''¡lejos sea de mí/de ti/de nosotros!'' Construida con la terminación locativa -ah sobre una raíz asociada con la profanación, proyecta la acción contemplada al ámbito de lo absolutamente inaceptable. Normalmente acompañada de un lamed de persona y min más infinitivo del acto repudiado. Abraham la usa dos veces al suplicar a Dios por Sodoma (Gn 18:25), los hermanos de José la invocan para negar el robo (Gn 44:7, 17), y David la emplea al negarse a dañar al ungido del Señor (1 S 26:11). A menudo reforzada con ''del Señor'' para subrayar que el acto rechazado violaría el orden divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97221, 'spa', 'Muda de ropa', 'Muda o juego de vestiduras, generalmente presentado como regalo de honor o apostado como premio. El plural ḥălīpōt śemālōt / begādīm (''mudas de ropa'') aparece en contextos de obsequio y apuesta. La generosidad de José con Benjamín (Gn 45:22) y las apuestas del acertijo de Sansón (Jue 14:12-13, 19) ilustran este uso, al igual que la oferta de Naamán a Giezi (2 R 5:5, 22-23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97222, 'spa', 'Relevo o turno', 'Cambio, turno, relevo o rotación de servicio en sentido más abstracto. Salomón organizó a los trabajadores de la madera del Líbano en turnos mensuales (1 R 5:14). Job usa el término metafóricamente para el relevo o descanso que espera tras el duro servicio de la muerte (Job 14:14). En Job 10:17 Dios envía tropas frescas -- ''cambios y guerra'' -- contra él. El Salmo 55:19 describe a los impíos complacientes como aquellos ''sin cambios''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97228, 'spa', 'Indefensos oprimidos', 'Personas indefensas o desvalidas que son víctimas de la opresión. Las tres apariciones se encuentran en el Salmo 10:8-14, donde describen al malvado que acecha «a los desvalidos», los asesina y los aplasta. Las dificultades textuales, incluidas las variantes ketiv/qeré, reflejan la antigua incertidumbre sobre esta palabra rara. Las versiones griega, siríaca y aramea la entendieron en términos de pobreza o aflicción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97230, 'spa', 'Profanar, contaminar', 'Profanar, violar o contaminar lo sagrado, tratando lo santo como común. Atestiguado en el participio Piel en Ez 28:9, donde el rey de Tiro será confrontado por ''los que te profanen''. Este sentido representa una violación sacra evidente. A veces se clasifica como una raíz separada (חלל II) en los léxicos estándar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97231, 'spa', 'Traspasar, herir mortalmente', 'Perforar, traspasar o herir de muerte, ya sea física o metafóricamente. Aplicado al combate cósmico (Job 26:13, traspasando a la serpiente), al sufrimiento vicario (Is 53:5, el Siervo herido por nuestras transgresiones) y a la angustia interior (Sal 109:22, el corazón traspasado). El español distingue bien: ''fue herido'' para Isaías, ''atravesados'' para los caídos en Ez 32:26.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97237, 'spa', 'Hifil: comenzar, iniciar', 'Hifil incoativo ''comenzar, iniciar'' — 56 ocurrencias, el segundo sentido más frecuente. Génesis 4:26 registra que la humanidad comenzó a invocar el nombre del SEÑOR; Génesis 6:1 marca cuándo los hombres ''comenzaron'' a multiplicarse; Génesis 9:20 presenta a Noé como quien ''comenzó'' a ser labrador. El español ''comenzó/empezó'' y el francés ''commença'' lo rinden uniformemente. El cognado árabe خَلَّ (desatar, aflojar) sugiere la metáfora de ''soltar las amarras''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97239, 'spa', 'Piel: profanar, contaminar', 'Piel intensivo ''profanar, contaminar, desacralizar'' — el sentido cúltico activo principal con 65 ocurrencias. Levítico concentra el uso: profanar el sábado (Éx 31:14), el nombre de Dios (Lv 19:12; 20:3), a una hija por prostitución (Lv 19:29) o la santidad sacerdotal (Lv 21). Ezequiel retoma el tema con la profanación del santuario de Jerusalén. El alemán ''entweihen'' y el español ''profanar'' lo traducen consistentemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97263, 'spa', 'Nifal/Pual: ser profanado', 'Formas pasivas Nifal y Pual: ser profanado, contaminado o desacralizado — la contrapartida pasiva del sentido 1 con 7 ocurrencias. Ezequiel domina: ''mis lugares santos fueron profanados'' (Ez 7:24), ''serás profanada a la vista de las naciones'' (Ez 22:16), ''sus sacerdotes profanaron y yo fui profanado entre ellos'' (Ez 22:26). Isaías 48:11 pregunta: ''¿Cómo habría de ser profanado mi nombre?''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97280, 'spa', 'Piel: usar el fruto', 'Uso agrícola-legal especializado del Piel: tratar el fruto recién plantado como común, es decir, ''desconsagrar'' la cosecha tras su período de עָרְלָה (incircuncisión). Deuteronomio 20:6 pregunta: ''¿Quién ha plantado una viña y no ha disfrutado aún de su fruto (חִלְּלוֹ)?'' — refiriéndose a la liberación del quinto año tras tres años de fruto prohibido y uno de ofrenda sagrada. Deuteronomio 28:30 amenaza con la maldición de plantar y no disfrutar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97294, 'spa', 'Hifil: profanar, quebrantar', 'Un raro causativo Hifil de la raíz ''profanar'' (distinto del Hifil ''comenzar''): hacer que sea profanado, violar o quebrantar un voto o pacto. Números 30:2 estipula que el hombre ''no profanará (יַחֵל) su palabra'' — debe mantener intacto su juramento. Ezequiel 39:7 registra la declaración de Dios: ''No dejaré que mi santo nombre sea profanado (אַחֵל) más.'' El español ''profanará/profanaré'' traduce estas formas con claridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97319, 'spa', 'muerto, traspasado mortalmente', 'muerto, traspasado mortalmente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97324, 'spa', 'herido, traspasado (lesionado)', 'herido, traspasado (lesionado)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97329, 'spa', 'cadáver, cuerpo sin vida', 'cadáver, cuerpo sin vida');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97360, 'spa', 'Profanado o mancillado', 'Profanado, mancillado o deshonrado: persona que ha quedado ceremonial o moralmente impura. En Levítico 21:7, 14, la forma femenina חֲלָלָה designa a una mujer sexualmente deshonrada; el Código de Santidad prohíbe a los sacerdotes casarse con tales mujeres. En Ezequiel 21:25, 29, la forma masculina se dirige a un ''profano e impío'', probablemente Sedequías, cuya realeza fue desacralizada por su infidelidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97362, 'spa', 'El sentido central del Qal finito', 'El sentido central del Qal finito: experimentar un sueño, particularmente uno cargado de significado profético o revelatorio. Es el uso dominante en 21 apariciones, abarcando todas las inflexiones del Qal. José declara ''soñé un sueño'' (Gn 37:9), el panadero y el copero de Faraón ''soñaron'' en prisión (Gn 40:5), e Isaías lo usa para la efímera frustración de los sueños que se desvanecen al despertar. Las traducciones convergen uniformemente en ''soñar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97364, 'spa', 'El sentido participial o de nombre de agente', 'El sentido participial o de nombre de agente: ''soñador'', quien sueña o se caracteriza por soñar. Con 5 apariciones, esta forma (cholem/cholmim) pasa del acto verbal a la persona que lo ejecuta. En Deuteronomio 13:1-5, el ''soñador de sueños'' aparece junto al profeta como alguien que reclama comunicación divina; la prueba legal es si el mensaje del sueño conduce hacia Yahvé o se aleja de él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97370, 'spa', 'Un uso nominal o semejante a sustantivo', 'Un uso nominal o semejante a sustantivo: el sueño mismo como objeto de experiencia. Aunque el sustantivo estándar es chalom, esta única aparición en Génesis 37:6 (''oíd este sueño'') puede reflejar un nombre verbal o construcción infinitiva donde el acto de soñar se funde con el contenido del sueño. La convergencia multilingüe sugiere que los hablantes percibían aquí una referencia nominal genuina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97373, 'spa', 'El Hifil causativo', 'El Hifil causativo: causar que se sueñe, inducir sueños en otros. Una sola aparición en Jeremías 29:8, donde se advierte a los exiliados que no dejen que sus profetas y adivinos ''os hagan soñar'', o posiblemente ''sueñen en vuestro nombre''. La raíz causativa señala que el soñar es provocado externamente en lugar de experimentarse espontáneamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97378, 'spa', 'Sustantivo arameo que designa un sueño experimentado durante el dormir, funciona', 'Sustantivo arameo que designa un sueño experimentado durante el dormir, funcionando como vehículo de revelación divina. En Daniel 2, Nabucodonosor exige que sus sabios relaten e interpreten su sueño; en Daniel 4:2-6 el rey mismo narra un sueño perturbador a Daniel; y en Daniel 7:1 el profeta recibe su propia visión apocalíptica en un sueño. Las formas enfáticas y sufijadas (mi sueño, tu sueño) aparecen repetidamente. Es cognado del hebreo chalom, y las traducciones en todas las lenguas lo vierten consistentemente como un sueño revelatorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97385, 'spa', 'Pedernal, roca dura', 'Pedernal, roca de sílex. Piedra de dureza excepcional, usada literalmente para la roca de la que Dios extrajo agua en el desierto (Dt 8:15; Sal 114:8) y para la roca trabajada por mineros (Job 28:9). En Dt 32:13 fluye aceite de roca de pedernal, hiperbólicamente. Is 50:7 lo emplea figuradamente para resolución inquebrantable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97386, 'spa', 'Nombre propio masculino', 'Helón, nombre propio masculino. Padre de Eliab, el líder designado de la tribu de Zabulón. Las cinco apariciones se encuentran en Números, en listas censales, disposiciones del campamento tribal y ofrendas de dedicación (Nm 1:9; 2:7; 7:24, 29; 10:16). Las tradiciones de la Septuaginta (Χαιλών, Χελών) reflejan una pronunciación con consonante gutural inicial conservada en las familias de manuscritos griegos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97387, 'spa', 'Hifil causativo', 'Hifil causativo: renovar o brotar de nuevo, la transformación positiva que sobreviene después de que algo ha pasado. Un árbol talado puede retoñar (Job 14:7), un arco se renueva en la mano (Job 29:20), y los que esperan en el Señor renovarán sus fuerzas (Is 40:31; 41:1). Paradójicamente, este sentido regenerativo brota de la misma raíz que ''pasar'' y ''perecer''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97388, 'spa', 'Piel/Hifil', 'Piel/Hifil: cambiar, intercambiar o reemplazar una cosa por otra. Abarca cambiarse de vestiduras (Gn 35:2; 41:14), alterar salarios (Gn 31:7, 41) y sustituir un animal sacrificial por otro (Lv 27:10). El cognado árabe khalafa (reemplazar, suceder) confirma este como sentido nuclear. Los equivalentes españoles ''cambiar'' y ''reemplazar'' convergen en la sustitución activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97391, 'spa', 'Qal intransitivo con peso existencial', 'Qal intransitivo con peso existencial: pasar, desvanecerse o dejar de existir, enfatizando la transitoriedad y la impermanencia. La lluvia cesó y se fue (Cnt 2:11), los cielos perecerán (Sal 102:26), y la vida humana brota y se marchita como la hierba (Sal 90:5-6). Se distingue del simple pasar por su énfasis en la extinción definitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97392, 'spa', 'Qal intransitivo', 'Qal intransitivo: pasar, atravesar o barrer en movimiento físico. Un espíritu pasa ante el rostro de Job (Job 4:15), Dios pasa inadvertido (Job 9:11), y naves veloces pasan como barcas de juncos (Job 9:26). El sentido es movimiento neutro a través del espacio, sin los matices destructivos o transformadores de otros sentidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97395, 'spa', 'Qal figurado', 'Qal figurado: violar o transgredir un pacto o una ley, tratando las obligaciones vinculantes como algo que se puede pasar por alto o ignorar. Atestiguado en Isaías 24:5, donde los habitantes de la tierra ''transgredieron las leyes, violaron el estatuto, quebrantaron el pacto eterno''. Marca la extensión legal-moral: traspasar un límite fijado por la autoridad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97401, 'spa', 'Qal transitivo', 'Qal transitivo: traspasar o penetrar, como un arma que atraviesa la carne. Jael clava la estaca de la tienda en la sien de Sísara (Jue 5:26), y una flecha de bronce traspasa al malvado (Job 20:24). El vínculo semántico con ''pasar a través'' es transparente: el arma pasa a través del cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97413, 'spa', 'Pasar, transcurrir', 'Pasar por encima, dicho del tiempo que transcurre sobre una persona (arameo). Las cuatro ocurrencias aparecen en Daniel 4:16, 23, 25 y 32, describiendo los siete ''tiempos'' que deben pasar sobre Nabucodonosor durante su locura impuesta por Dios. El verbo lleva עַל (''sobre'') con la persona, evocando la imagen vívida del tiempo rodando sobre alguien impotente para detenerlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97416, 'spa', 'Nifal (pasivo)', 'Nifal (pasivo): ser rescatado o librado del peligro. El justo ''es librado'' de la angustia (Pr 11:8), y los amados ''serán librados'' por el poder de Dios (Sal 60:5; 108:6). Proverbios 11:8-9 empareja el Nifal y el sentido activo en contraste instructivo: el justo es librado, pero el malvado toma su lugar en la tribulación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97417, 'spa', 'Piel (causativo-intensivo)', 'Piel (causativo-intensivo): rescatar, librar o salvar a alguien del peligro, la angustia o los enemigos. Es el sentido más frecuente (11 apariciones). Dios rescata al salmista llevándolo a un ''lugar espacioso'' (2 S 22:20; Sal 18:19), libra al afligido a través del sufrimiento (Job 36:15) y promete ''yo lo rescataré'' (Sal 91:15). Las traducciones convergen uniformemente en ''librar/rescatar'', confirmando este como el sentido dominante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97418, 'spa', 'Qal', 'Qal: sacar, quitar o despojar algo físico. Deuteronomio 25:9 prescribe que la viuda rechazada ''quitará'' la sandalia de su cuñado, e Isaías 20:2 registra que Dios ordena a Isaías ''quitarse'' las sandalias. Lamentaciones 4:3 extiende la imagen a los chacales que ''sacan el pecho'' para amamantar a sus crías. El español ''quitar/sacar'' capta con claridad la extracción física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97421, 'spa', 'Piel con extracción violenta', 'Piel con extracción violenta: arrancar piedras o saquear. Levítico 14:40-43 describe cómo arrancar piedras contaminadas de la pared de una casa, mientras que Salmo 7:4 emplea la imagen de despojar o saquear. El cognado árabe khalasa (retirar, extraer) y el arameo chalats (despojar) confirman este sentido de extracción más violenta. El español ''arrancar'' transmite la fuerza que lo distingue de la simple remoción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97433, 'spa', 'Qal intransitivo', 'Qal intransitivo: retirarse o apartarse de una situación. Una sola aparición en Oseas 5:6 describe a Dios habiéndose ''retirado'' de Israel infiel. El cognado árabe khalasa (retirarse, apartarse) confirma este sentido reflexivo de alejarse. Es la imagen inversa de la liberación del Piel: en lugar de que Dios extraiga a su pueblo del peligro, aquí Dios se extrae a sí mismo de su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97438, 'spa', 'Armado, equipado para la guerra — el participio pasivo Qal chaluts usado adjetiv', 'Armado, equipado para la guerra — el participio pasivo Qal chaluts usado adjetival y sustantivamente para guerreros listos para la batalla. Con 17 apariciones, este sentido dominante funciona como término técnico militar en las narrativas de la conquista: ''todo hombre armado de vosotros cruzará el Jordán'' (Nm 32:21), la vanguardia armada marchando delante del arca en Jericó (Jos 6:7, 9, 13), y el censo de guerreros equipados en Crónicas. Las traducciones convergen en ''armado/equipado''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97442, 'spa', 'Armarse — el Nifal reflexivo que expresa el acto volitivo de tomar las armas y p', 'Armarse — el Nifal reflexivo que expresa el acto volitivo de tomar las armas y prepararse para la batalla. Se encuentra en 3 apariciones, todas en las negociaciones entre Moisés y las tribus transjordanas: ''Armad a algunos de vuestros hombres para la guerra'' (Nm 31:3), ''Nos armaremos'' (Nm 32:17) y ''Si se arman delante del Señor'' (Nm 32:20). La construcción reflexiva marca la preparación deliberada y voluntaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97447, 'spa', 'Fortalecer o fortificar — un Hifil causativo que significa hacer fuerte, represe', 'Fortalecer o fortificar — un Hifil causativo que significa hacer fuerte, representando la semántica subyacente de vigor de la raíz, aparte del equipamiento militar. Solo 1 aparición: ''El Señor te guiará siempre y saciará tu deseo en tierras áridas, y fortalecerá tus huesos'' (Is 58:11). El cambio al vocabulario dedicado de fuerza confirma un sentido genuinamente distinto del armamento bélico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97453, 'spa', 'Nombre propio personal', 'Heles, nombre personal que significa «vigor». Designa a (a) uno de los valientes de David, del clan paltita/pelonita (2 S 23:26; 1 Cr 11:27; 27:10), y (b) un hombre en la genealogía de Judá descendiente de Jerameel (1 Cr 2:39). La Septuaginta muestra variación considerable (Σελλής, Ἑλλής, Χελλής), indicando inestabilidad fonética temprana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97454, 'spa', 'Lomos (parte corporal)', 'Los lomos como parte física del cuerpo, especialmente como sede del poder reproductivo y la fuerza corporal. ''De tus lomos saldrán reyes'' (Gn 35:11) y ''el que saldrá de tus lomos'' (1 R 8:19; 2 Cr 6:9) emplean chalatsayim para la fuente de descendencia. Job 38:3 y 40:7 ordenan ''ciñe tus lomos como hombre'', invocando la parte media del cuerpo como centro de disposición física. Job 31:20 describe los lomos del pobre calentados por las vestiduras del justo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97459, 'spa', 'Cintura (para ceñir)', 'La cintura específicamente como punto donde se ciñe un cinturón o faja, enfatizando el lugar de sujeción externa más que el poder reproductivo. Isaías 11:5 emplea este sentido en un retrato mesiánico: ''la fidelidad será el cinturón de sus lomos (chalatsav)''. Aquí el enfoque recae en lo que rodea la cintura -- justicia y fidelidad como vestiduras -- y no en lo que procede de los lomos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97462, 'spa', 'distribuir, repartir (Piel)', 'distribuir, repartir (Piel)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97463, 'spa', 'ser dividido (Nifal pasivo)', 'ser dividido (Nifal pasivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97465, 'spa', 'dividir, compartir, asignar (Qal)', 'dividir, compartir, asignar (Qal)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97473, 'spa', 'Ocurrencia ambigua en Jeremías 37', 'Ocurrencia ambigua en Jeremías 37:12 donde Jeremías sale para ''recibir una porción'' o ''escabullirse'' entre su pueblo; probablemente un infinitivo Hifil con el sentido de asegurar su herencia en Benjamín durante el asedio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97475, 'spa', 'ser distribuido (Pual pasivo)', 'ser distribuido (Pual pasivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97496, 'spa', 'Forma Qal futura en Josué 18', 'Forma Qal futura en Josué 18:5 que describe la intención de Israel de dividir la tierra restante en porciones entre las tribus.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97503, 'spa', 'Uso único en Lamentaciones 4', 'Uso único en Lamentaciones 4:16 donde el rostro de Dios ''dispersó'' a los sacerdotes y ancianos — el verbo pasa de su dominio habitual de repartición al de dispersión forzosa como juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97508, 'spa', 'Adular, alisar el habla', 'Adular, usar palabras lisas o engañosas (Hifil). El sentido más frecuente: hacer las palabras peligrosamente resbaladizas para manipular. Proverbios 2:16 y 7:5 advierten contra la mujer extraña que «alisa sus palabras»; el Salmo 36:2 describe al malvado que «se adula a sí mismo»; el Salmo 5:9 señala la lengua que «alisa» para seducir. Es la adulación como arma retórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97511, 'spa', 'Ser liso (físico)', 'Ser liso o resbaladizo en sentido físico (Qal/Hifil). El Salmo 55:21 describe palabras «suaves como la mantequilla», aunque incluso aquí la imagen física sirve a un propósito moral. Isaías 41:7 ofrece el único uso puramente literal: un artesano «alisando con el martillo» mientras fabrica un ídolo. Es la base concreta de la que brota toda la metáfora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97513, 'spa', 'Estar dividido, resbaladizo', 'Estar dividido o partido, referido a un corazón infiel (Qal). Oseas 10:2 declara «su corazón está dividido», diagnosticando el intento de Israel de adorar a YHWH y a los baales. La LXX traduce con ἐμέρισαν (''dividieron''), favoreciendo la lectura de división, aunque puede tratarse de un juego de palabras profético: un corazón «resbaladizo» es también un corazón «partido».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97516, 'spa', 'porción, parte, asignación', 'porción, parte, asignación');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97522, 'spa', 'parcela de tierra, terreno', 'parcela de tierra, terreno');